#!/usr/bin/env python3
"""Insère des paragraphes « Vérification » avant la fin de la k-ième question du corrigé (fr et en)."""
import re, sys
SITE='/home/claude/site'
def insert(n, checks):
    f=f'{SITE}/mf{n}.html'; d=open(f,encoding='utf-8').read()
    for lang in ('fr','en'):
        i=d.find(f'I18N.{lang}.sol = function'); j=d.find('\n};\n',i)+4
        sol=d[i:j]
        lbl='Vérification.' if lang=='fr' else 'Check.'
        closers=[m.start() for m in re.finditer(r'</div></li>', sol)]
        assert len(closers)>=len(checks), (n,lang,len(closers))
        # insérer de la fin vers le début pour garder les positions
        for q in sorted(checks.keys(), reverse=True):
            txt=checks[q][0 if lang=='fr' else 1]
            if not txt: continue
            pos=closers[q-1]
            sol=sol[:pos]+f'\n  <p class="check"><span class="chk-lbl">{lbl}</span>{txt}</p>\n'+sol[pos:]
        d=d[:i]+sol+d[j:]
    open(f,'w',encoding='utf-8').write(d); print(f'mf{n}: {len(checks)} vérifications')

